export const DEFAULT_PHYSICS={gravity:9.81,friction:.24,bounce:.12,contacts:true,rigid:false,balls:[]};
export function physicsSettings(value){if(value===undefined)return {...DEFAULT_PHYSICS,balls:[]};if(!value||typeof value!=='object')throw Error('Invalid physics settings');const p={...DEFAULT_PHYSICS,...value};for(const [key,min,max] of [['gravity',0,20],['friction',0,1],['bounce',0,.8]])if(!Number.isFinite(p[key])||p[key]<min||p[key]>max)throw Error('Invalid physics '+key);for(const key of ['contacts','rigid'])if(typeof p[key]!=='boolean')throw Error('Invalid physics '+key);if(!Array.isArray(p.balls)||p.balls.length>32||p.balls.some(b=>!b||!Array.isArray(b.pos)||b.pos.length!==3||b.pos.some(n=>!Number.isFinite(n)||Math.abs(n)>10000)||b.pos[1]<23))throw Error('Invalid ball positions');return{gravity:p.gravity,friction:p.friction,bounce:p.bounce,contacts:p.contacts,rigid:p.rigid,balls:p.balls.map(b=>({pos:[...b.pos]}))};}
